    Gigabytes = byteSize / BytesInGigabyte;
    Terabytes = byteSize / BytesInTerabyte;
}

// After: 8-byte struct, 0 divisions per construction
public DataSize(double byteSize)
{
    Bits = (long)Math.Ceiling(byteSize * BitsInByte);
}

public long Bits { get; }
public double Bytes => (double)Bits / BitsInByte;
public double Kilobytes => Bytes / BytesInKilobyte;
// ... etc
```

#### 2. Closure Allocation in ToString via Local Functions (2 instances)
**Impact:** The local functions `has` and `output` (L183-184) capture mutable locals `format`, `culture`, and `formatProvider`. The compiler generates a heap-allocated display class for every `ToString()` call — one allocation before any formatting even begins.
**Files:** DataSize.cs:L183-184
**Fix:** Inline the logic or pass captured variables as parameters to the local functions to avoid the closure.

```csharp
// Before: captures format, culture, formatProvider → heap-allocated display class
bool has(string s) => culture.CompareInfo.IndexOf(format, s, CompareOptions.IgnoreCase) != -1;
string output(double n) => n.ToString(format, formatProvider);

// After: pass as parameters → no closure allocation
static bool has(ReadOnlySpan<char> fmt, string s, CultureInfo c)
    => c.CompareInfo.IndexOf(fmt.ToString(), s, CompareOptions.IgnoreCase) != -1;
// Or simply inline the one-liner at each call site
```

